def convert_openhands_message(msg: dict) -> tuple[str, str]:
    """Convert a single OpenHands message to (role, text) in our format.

    Returns:
        (role, text) where role is "system", "user", or "ai"
    """
    oh_role = msg.get("role", "")
    content = msg.get("content") or ""
    tool_calls = msg.get("tool_calls") or []

    if oh_role == "system":
        return "system", content

    if oh_role == "user":
        return "user", content

    if oh_role == "assistant":
        parts = []
        if content:
            parts.append(content)
        for tc in tool_calls:
            cmd_text = _format_tool_call(tc)
            parts.append(f"```\n{cmd_text}\n```")
        return "ai", "\n\n".join(parts) if parts else content

    if oh_role == "tool":
        return "user", content

    return "user", content


def convert_openhands_trajectory(raw: dict, row_index: int = 0) -> Trajectory:
    """Convert a raw OpenHands record dict to our Trajectory format.

    Args:
        raw: Dict with keys from the OpenHands parquet: trajectory_id, instance_id,
             trajectory (list of message dicts), exit_status, resolved, model_patch.
        row_index: Source file line number.
    """
    oh_traj = raw.get("trajectory") or []
    steps = []
    for i, msg in enumerate(oh_traj):
        role, text = convert_openhands_message(msg)
        steps.append(Step(
            index=i,
            role=role,
            text=text,
            mask=False,
            system_prompt=text if role == "system" and i == 0 else None,
        ))

    resolved = raw.get("resolved", 0)
    target = bool(resolved) if isinstance(resolved, (int, float)) else False

    return Trajectory(
        instance_id=raw.get("instance_id", ""),
        model_name="openhands",
        target=target,
        steps=steps,
        exit_status=raw.get("exit_status", ""),
        generated_patch=raw.get("model_patch"),
        eval_logs=None,
        row_index=row_index,
    )


def convert_trajectory_to_serializable(traj: Trajectory) -> dict:
    """Convert to the same JSONL format used by SWE-agent data_loader."""
    steps_out = []
    for s in traj.steps:
        d = {"role": s.role, "text": s.text, "mask": s.mask}
        if s.cutoff_date:
            d["cutoff_date"] = s.cutoff_date
        if s.system_prompt:
            d["system_prompt"] = s.system_prompt
        steps_out.append(d)

    return {
        "instance_id": traj.instance_id,
        "model_name": traj.model_name,
        "target": traj.target,
        "trajectory": steps_out,
        "exit_status": traj.exit_status,
        "generated_patch": traj.generated_patch,
        "eval_logs": traj.eval_logs,
    }


